import{_ as l,a0 as n,w as p,s as d,ao as r,I as o,x as t,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"將 Zeek 與 ELK 棧集成 | LCTT x X-CMD","titleTemplate":false,"description":"將 Zeek 與 ELK 棧集成 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"將 Zeek 與 ELK 棧集成 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"將 Zeek 與 ELK 棧集成 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220607 Integrating Zeek with ELK Stack","title":"將 Zeek 與 ELK 棧集成","tag":"202206","desc":""},"relativePath":"202206/20220607 Integrating Zeek with ELK Stack.md","filePath":"[post].md"}'),c={name:"202206/20220607 Integrating Zeek with ELK Stack.md"};function g(k,e,h,u,b,f){const s=n("Link");return p(),d("div",null,[e[15]||(e[15]=r(`<h1 id="將-zeek-與-elk-棧集成" tabindex="-1">將 Zeek 與 ELK 棧集成 <a class="header-anchor" href="#將-zeek-與-elk-棧集成" aria-label="Permalink to “將 Zeek 與 ELK 棧集成”">​</a></h1><blockquote><p>Zeek 是一個開源的網絡安全監控工具。本文討論瞭如何將 Zeek 與 ELK 集成。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202206/28/164550v4nuk3g7ux77y77v.jpg" alt=""></p><p>在本雜誌 2022 年 3 月版發表的題為“用 Zeek 輕鬆實現網絡安全監控”的文章中，我們研究了 Zeek 的功能，並學習瞭如何開始使用它。現在我們將把我們的學習經驗再進一步，看看如何將其與 ELK（即 Elasticsearch、Kibana、Beats 和 Logstash）整合。</p><p>為此，我們將使用一個叫做 Filebeat 的工具，它可以監控、收集並轉發日誌到 Elasticsearch。我們將把 Filebeat 和 Zeek 配置在一起，這樣後者收集的數據將被轉發並集中到我們的 Kibana 儀表盤上。</p><h3 id="安裝-filebeat" tabindex="-1">安裝 Filebeat <a class="header-anchor" href="#安裝-filebeat" aria-label="Permalink to “安裝 Filebeat”">​</a></h3><p>讓我們首先將 Filebeat 與 Zeek 安裝在一起。使用 <code>apt</code> 來安裝 Filebeat，使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install filebeat</span></span></code></pre></div><p>接下來，我們需要配置 <code>.yml</code> 文件，它位於 <code>/etc/filebeat/</code> 文件夾中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nano /etc/filebeat/filebeat.yml</span></span></code></pre></div><p>我們只需要在這裏配置兩件事。在 Filebeat 輸入部分，將類型改為 <code>log</code>，並取消對 <code>enabled:false</code> 的註釋，將其改為 <code>true</code>。我們還需要指定存儲日誌的路徑，也就是説，我們需要指定 <code>/opt/zeek/logs/current/*.log</code>。</p><p>完成這些後，設置的第一部分應該類似於圖 1 所示的內容。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-1-Filebeat-config-a.jpg" alt="Figure 1: Filebeat config (a)"></p><p>第二件要修改的事情是在輸出下的 Elasticsearch 輸出部分，取消對 <code>output.elasticsearch</code> 和 <code>hosts</code> 的註釋。確保主機的 URL 和端口號與你安裝 ELK 時配置的相似。我們把它保持為 <code>localhost</code>，端口號為 <code>9200</code>。</p><p>在同一部分中，取消底部的用户名和密碼的註釋，輸入安裝後配置 ELK 時生成的 Elasticsearch 用户的用户名和密碼。完成這些後，參考圖 2，檢查設置。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-2-Filebeat-config-b.jpg" alt="Figure 2: Filebeat config (b)"></p><p>現在我們已經完成了安裝和配置，我們需要配置 Zeek，使其以 JSON 格式存儲日誌。為此，確保你的 Zeek 實例已經停止。如果沒有，執行下面的命令來停止它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /opt/zeek/bin</span></span>
<span class="line"><span>./zeekctl stop</span></span></code></pre></div><p>現在我們需要在 <code>local.zeek</code> 中添加一小行，它存在於 <code>opt/zeek/share/zeek/site/</code> 目錄中。</p><p>以 root 身份打開該文件，添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@load policy/tuning/json-logs.zeek</span></span></code></pre></div><p>參考圖 3，確保設置正確。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-3-local.zeek-file-1.jpg" alt="Figure 3: local.zeek file"></p><p>由於我們改變了 Zeek 的一些配置，我們需要重新部署它，這可以通過執行以下命令來完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /opt/zeek/bin</span></span>
<span class="line"><span>./zeekctl deploy</span></span></code></pre></div><p>現在我們需要在 Filebeat 中啓用 Zeek 模組，以便它轉發 Zeek 的日誌。執行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo filebeat modules enable zeek</span></span></code></pre></div><p>我們幾乎要好了。在最後一步，配置 <code>zeek.yml</code> 文件要記錄什麼類型的數據。這可以通過修改 <code>/etc/filebeat/modules.d/zeek.yml</code> 文件完成。</p><p>在這個 .yml 文件中，我們必須提到這些指定的日誌存放在哪個目錄下。我們知道，這些日誌存儲在當前文件夾中，其中有幾個文件，如 <code>dns.log</code>、<code>conn.log</code>、<code>dhcp.log</code> 等等。我們需要在每個部分提到每個路徑。如果而且只有在你不需要該文件/程序的日誌時，你可以通過把啓用值改為 <code>false</code> 來捨棄不需要的文件。</p><p>例如，對於 <code>dns</code>，確保啓用值為 <code>true</code>，並且路徑被配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var.paths: [ “/opt/zeek/logs/current/dns.log”, “/opt/zeek/logs/*.dns.json” ]</span></span></code></pre></div><p>對其餘的文件重複這樣做。我們對一些我們需要的文件做了這個處理。我們添加了所有主要需要的文件。你也可以這樣做。請參考圖 4。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-4-zeek.yml-configuration.jpg" alt="Figure 4: zeek.yml configuration"></p><p>現在是啓動 Filebeat 的時候了。執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo filebeat setup</span></span>
<span class="line"><span>sudo service filebeat start</span></span></code></pre></div><p>現在一切都完成了，讓我們移動到 Kibana 儀表板，檢查我們是否通過 Filebeat 接收到來自 Zeek 的數據。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-5-Dashboard-of-Kibana-Destination-Geo.jpg" alt="Figure 5: Dashboard of Kibana (Destination Geo)"></p><p>進入儀表板。你可以看到它所捕獲的數據的清晰統計分析（圖 5 和圖 6）。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-6-Dashboard-of-Kibana-Network-1.jpg" alt="Figure 6: Dashboard of Kibana (Network)"></p><p>現在讓我們進入發現選項卡，通過使用查詢進行過濾來檢查結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>event.module: &quot;zeek&quot;</span></span></code></pre></div><p>這個查詢將過濾它在一定時間內收到的所有數據，只向我們顯示名為 Zeek 的模組的數據（圖 7）。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-7-Filtered-data-by-event.jpg" alt="Figure 7: Filtered data by event.module query"></p><h3 id="鳴謝" tabindex="-1">鳴謝 <a class="header-anchor" href="#鳴謝" aria-label="Permalink to “鳴謝”">​</a></h3><p><em>作者感謝 VIT-AP 計算機科學與工程學院的 Sibi Chakkaravarthy Sethuraman、Sudhakar Ilango、Nandha Kumar R.和Anupama Namburu 的不斷指導和支持。特別感謝人工智能和機器人技術卓越中心（AIR）。</em></p><hr>`,46)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),a(s,{href:"https://www.opensourceforu.com/2022/06/integrating-zeek-with-elk-stack/"},{default:i(()=>[...e[0]||(e[0]=[t("https://www.opensourceforu.com/2022/06/integrating-zeek-with-elk-stack/",-1)])]),_:1})]),o("p",null,[e[6]||(e[6]=t("作者：",-1)),a(s,{href:"https://www.opensourceforu.com/author/tridev-reddy/"},{default:i(()=>[...e[2]||(e[2]=[t("Tridev Reddy",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),a(s,{href:"https://github.com/lkxed"},{default:i(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),a(s,{href:"https://github.com/geekpi"},{default:i(()=>[...e[4]||(e[4]=[t("geekpi",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),a(s,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),a(s,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const C=l(c,[["render",g]]);export{y as __pageData,C as default};
